-- Service: search  (per cell)
-- GENERATED by tools/split.py from plan/db/*.sql. Edit the source files or split.py, then re-run.
-- Load order: _prelude.sql, search.sql, _epilogue.sql
-- browse recent by type
-- (add pg_trgm + a trigram GIN on title later if prefix/typo search is needed.)

-- index state = outbox for retries and for a future external engine. One row per entity needing (re)index or removal.
CREATE TABLE search_index_state (
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  entity_type text NOT NULL,
  entity_id uuid NOT NULL,
  desired_version integer NOT NULL DEFAULT 0,        -- latest version seen in change_log
  indexed_version integer NOT NULL DEFAULT 0,
  op text NOT NULL DEFAULT 'upsert' CHECK (op IN ('upsert','delete')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','indexed','failed')),
  attempts smallint NOT NULL DEFAULT 0,
  last_error text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, entity_type, entity_id)
);

CREATE INDEX search_index_state_todo ON search_index_state (updated_at) WHERE status <> 'indexed';

CREATE TABLE saved_searches (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  user_id uuid NOT NULL /* id -> identity.users */,
  name text NOT NULL, query text NOT NULL, filters jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);
